#include <string.h>
#include <stdint.h>

void process_utf16_to_utf8(char *szLine, int unicode_type) {
    int i = 0;
    while (szLine[i] != '\0' || szLine[i + 1] != '\0') {
        uint16_t *wchar = (uint16_t *)&szLine[i];
        if (*wchar == 0) {
            break;
        }

        if (unicode_type == 1) {
            // Big-endian: do nothing, already in BE format
        } else {
            // Little-endian: swap bytes
            *wchar = ((*wchar >> 8) | (uint16_t)((*wchar & 0xFF) << 8));
        }

        i += 2;
    }
}

